// Arbeitnow returns about 100 jobs per page, newest first. 10 pages covers
// roughly the last couple of weeks.
const PAGES = 10;
return Array.from({ length: PAGES }, (_, i) => ({ json: { page: i + 1 } }));

// Bundesagentur für Arbeit searches for people who will own an AI rollout.
const QUERIES = [
  'KI-Manager', 'KI Manager', 'AI Manager', 'Head of AI', 'Leiter KI', 'Leitung KI',
  'KI-Beauftragter', 'KI-Koordinator', 'KI-Referent', 'KI-Transformation', 'AI Transformation',
  'AI Enablement', 'AI Adoption', 'KI-Einführung', 'AI Lead', 'KI Lead', 'KI-Strategie',
  'AI Governance', 'KI Governance', 'Microsoft Copilot', 'ChatGPT', 'Product Owner KI',
];
return QUERIES.map(query => ({ json: { query } }));

// Flatten the search results, keep titles that are about AI, drop repeats,
// and build the detail URL (the API wants the reference number in base64).
const AI_TITLE = /\b(ai|ki|künstliche intelligenz|artificial intelligence|genai|llm)\b|copilot|chatgpt/i;
const MAX_DETAILS = 250;
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  for (const s of (item.json.ergebnisliste || [])) {
    const ref = s.referenznummer;
    if (!ref || seen.has(ref) || !AI_TITLE.test(s.stellenangebotsTitel || '')) continue;
    seen.add(ref);
    out.push({ json: {
      referenznummer: ref,
      detailUrl: 'https://rest.arbeitsagentur.de/jobboerse/jobsuche-service/pc/v4/jobdetails/' + Buffer.from(ref).toString('base64'),
    } });
  }
}
return out.slice(0, MAX_DETAILS);

// Score companies from Arbeitnow job posts. Port of ai_rollout_signals.py.
// Input: one item per API page ({ data: [jobs] }). Output: one item per company
// with at least one AI signal. Points: +40 AI owner, +30 rollout, +20 GDPR + AI,
// +10 looks mid-size or large (heuristic).

const POINTS = { ai_owner: 40, rollout: 30, gdpr_ai: 20, size: 10 };

const plain = (s) => (s || '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/\s+/g, ' ').trim();

// ---- DACH filter
const DACH_CODES = /\b(DE|AT|CH|DEU|AUT|CHE)\b/;
const DACH = /(deutschland|germany|dach|österreich|austria|schweiz|switzerland|berlin|münchen|munich|hamburg|köln|cologne|frankfurt|stuttgart|düsseldorf|leipzig|dresden|hannover|nürnberg|nuremberg|bremen|essen|dortmund|bochum|bonn|mannheim|karlsruhe|heidelberg|münster|augsburg|wiesbaden|mainz|darmstadt|freiburg|aachen|kiel|potsdam|chemnitz|kassel|bielefeld|regensburg|ingolstadt|würzburg|ulm|heilbronn|bayern|bavaria|hessen|sachsen|niedersachsen|nordrhein|wien|vienna|graz|linz|salzburg|innsbruck|zürich|zurich|basel|bern|genf|geneva|lausanne|luzern|zug|st\. ?gallen)/i;
const NON_DACH = /\b(london|uk|united kingdom|paris|france|amsterdam|netherlands|madrid|barcelona|spain|lisbon|milan|italy|dublin|warsaw|poland|prague|stockholm|copenhagen|brussels|usa|united states|canada|new york|india|singapore)\b/i;
const GERMAN = /\b(und|wir|sie|die|der|das|für|mit|unser|unsere|ihre|deine|bei)\b/gi;
function isDach(loc, text) {
  if (DACH.test(loc) || DACH_CODES.test(loc)) return true;
  if (NON_DACH.test(loc)) return false;
  return ((text.slice(0, 3000).match(GERMAN)) || []).length >= 25;
}

// ---- signals
const TITLE_AI = /\b(ai|ki|künstliche intelligenz|artificial intelligence|genai|llm)\b/i;
const OWNER_TITLE = new RegExp([
  'head of (ai|artificial intelligence|genai|generative ai|ki|künstliche intelligenz)\\b',
  '\\b(leiter|leiterin|leitung|referent|referentin|manager|managerin|koordinator|beauftragte[rn]?|verantwortliche[rn]?)\\s+(für\\s+)?(ki|künstliche intelligenz|ai)\\b',
  '\\b(ki|ai|genai)[- ](lead|manager|managerin|beauftragte[rn]?|officer|champion|koordinator\\w*|referent\\w*|owner|project manager|projektleit\\w*|transformation\\w*|enablement|adoption|governance|strategy|strategie|innovation|operations|change)\\b',
  '\\b(ki|ai)[- ]?(&|und|and)\\s+(automation|automatisierung|digitalisierung|digital\\w*)\\s+(lead|manager\\w*|specialist|spezialist\\w*|owner)\\b',
  '\\b(enablement|adoption|innovation|governance|strategy|strategie|automation|automatisierung|operations|digitalisierung)\\b.{0,25}\\b(ai|ki)\\b',
  '\\bproduct owner\\b.{0,25}\\b(ai|ki)\\b',
].join('|'), 'i');
const BUILDER_TITLE = /\b(engineer|engineering|entwickler\w*|developer|scientist|research\w*|architect\w*|annotation|trainer|tester|evaluation|sales|account executive|account manager|business development|vertrieb\w*|marketing|seo|content|creator|designer|recruit\w*|consultant|\w*berater\w*|presales|solution\w*|social media|growth|search|security|cyber\w*|jurist\w*|policy)\b/i;
const JUNIOR_TITLE = /(werkstudent|working student|praktik|\bintern\b|internship|trainee|thesis|azubi|ausbildung|\bstudent\b|\bjunior\b|dual)/i;
const PRODUCT_OR_DATA = /\b(product (owner|manager|lead)|produktmanager\w*|data science|analytics|machine learning)\b/i;
const CLIENT_FACING = /\b(sales|account executive|account manager|business development|vertrieb\w*|consultant|\w*berater\w*|presales|solution\w*|forward deployed|customer success|implementation|deployment|trainer)\b/i;

const AI = '(?:ki|ai|genai|generative[nrs]? (?:ki|ai)|künstliche[nr]? intelligenz|llms?|chatgpt|copilot)(?![- ](?:assisted|generated|powered|driven|native|based|coding|code|search))';
const STAFF = '(?:mitarbeitende\\w*|mitarbeiter\\w*|beschäftigte\\w*|kolleg\\w+|belegschaft|employees|staff|workforce|colleagues|fachbereiche\\w*|fachabteilungen|abteilungen|teams|business units)';
const OUR = '(?:our|unsere[nmrs]?|des unternehmens|konzernweit\\w*|unternehmensweit\\w*)';
const ROLLOUT = [
  ['KI-Einführung', '\\bki[- ]einführung\\b|einführung (?:von |der |neuer )?(?:generativer |generativen )?(?:ki|künstlicher intelligenz|ai)\\b|einführung (?:von |der |neuer )?(?:ki|ai)[- ]\\w+|einsatz von (?:ki|künstlicher intelligenz) (?:im unternehmen|bei uns)'],
  ['AI adoption across the company', '\\b(?:ai|ki|genai)[- ]adoption\\b[^.]{0,80}\\b(?:across|throughout|within) (?:the |our )?(?:company|organi[sz]ation|business|group|teams)|\\b(?:drive|driving|lead|leading|accelerat\\w+|foster\\w*)\\b (?:the )?(?:(?:ai|genai|ki)[- ]adoption|adoption of (?:generative )?(?:ai|genai))\\b'],
  ['AI rollout', '\\b(?:ai|ki|copilot|genai|llm)[- ]roll-?outs?\\b|\\broll(?:ing)?[- ]out (?:of )?(?:generative )?(?:ai|ki|copilot|genai)\\b'],
  ['ChatGPT Enterprise', '\\bchatgpt (?:enterprise|team|business)\\b'],
  ['Microsoft Copilot', '\\b(?:microsoft|ms|m365|microsoft 365) ?copilot\\b|\\bcopilot studio\\b'],
  ['Azure OpenAI', '\\bazure openai\\b'],
  ['an internal AI strategy', OUR + ' (?:ki|ai|genai)[- ](?:strategie|strategy|roadmap|initiativen|initiatives|programm?e?)\\b'],
  ['internal AI tools', '\\b(?:intern\\w*|internal)[- ](?:ki|ai|genai|llm)[- ]?(?:tools?|lösungen|anwendungen|assistenten|assistants?|plattform|platform|chatbots?|agenten|agents)\\b'],
  ['AI for the whole company',
    '\\b' + AI + '\\b[^.]{0,80}\\b(?:across|throughout) (?:the |our |all )?(?:company|organi[sz]ation|business|' + STAFF + ')\\b' +
    '|\\b(?:unternehmensweit\\w*|konzernweit\\w*|company-wide|organi[sz]ation-wide)\\b[^.]{0,60}\\b' + AI + '\\b' +
    '|\\b' + AI + '\\b[^.]{0,60}\\b(?:unternehmensweit\\w*|konzernweit\\w*|company-wide)\\b' +
    '|\\b(?:für|for) (?:unsere|our|alle|all) ' + STAFF + '\\b[^.]{0,60}\\b' + AI + '\\b'],
  ['AI enablement / training for staff', '\\b(?:ki|ai)[- ](?:enablement|befähigung)\\b|\\bai champions?\\b|\\bki[- ](?:champions?|botschafter\\w*)|\\bai literacy\\b|\\bki[- ]schulung'],
  ['AI governance', '\\b(?:ki|ai)[- ]governance\\b'],
].map(([label, p]) => [label, new RegExp(p, 'i')]);
const AI_WORD = /\b(ki|ai|künstliche\w* intelligenz|artificial intelligence|genai|llms?|chatgpt|copilot|generative\w*)\b/i;
const GDPR = /(dsgvo|gdpr|datenschutz\w*|data protection|data privacy|eu ai act|\bai act\b|ki-verordnung)/gi;
const SIZE_TEXT = /\b(konzern\w*|mittelstand\w*|mittelständisch\w*|marktführer\w*|market leader|familienunternehmen|börsennotiert\w*|standorten|offices in|niederlassungen|tochtergesellschaft\w*)\b|\b(\d{1,3}[.,]\d{3}|\d{3,})\+?\s*(mitarbeitende\w*|mitarbeiter\w*|beschäftigte\w*|employees|colleagues)\b/i;

// ---- exclusions: Langdock, competitors, AI vendors, agencies, consultancies
const EXCLUDE = new Set(['langdock', 'openai', 'microsoft', 'glean', 'anthropic', 'google', 'alephalpha', 'deepl', 'deeplse',
  'mistralai', 'cohere', 'nvidia', 'amazon', 'aws', 'ibm', 'salesforce', 'servicenow', 'sap', 'neulandai', 'celonis',
  'jetbrains', 'datadog', 'intercom', 'parloa', 'n8n', 'ionos', 'telekom', 'databricks', 'snowflake', 'nebius',
  'jobgether', 'accenture', 'capgemini', 'deloitte', 'pwc', 'kpmg', 'mckinsey', 'bcg', 'adesso', 'computacenter',
  'bechtle', 'cancom', 'nttdata', 'bridgingit', 'communardo', 'cbscorporatebusinesssolutions']);
const VENDOR_NAME = /(\.ai\b|\bai\b|\bki\b|\w+ai$|\bmachine learning\b|\bintelligence\b|\bgpt\b|\bllm\b)/i;
const VENDOR_TEXT = /\b(ai|ki)[- ](startup|start-up|scale-?up|company|native|lab|labs)\b|\b(we|wir) (are|sind) (an? |ein\w* )?(\w+ ){0,3}(ai|ki)[- ]?(startup|company|unternehmen|platform|plattform|anbieter)\b|\b(we|wir) (build|develop|entwickeln|bauen)\s+(\w+ ){0,4}(ai|ki|llm|genai|agent\w*)[- ]?(products?|platform|plattform|agents?|lösung\w*|solutions?|software|models?)\b|\b(ai|ki|genai)[- ](powered|native|driven|based)\s+(\w+ ){0,2}(platform|plattform|software|saas|product|solution|startup)\b|\bfoundation models?\b|\bai health[- ]?tech\b|\bhealthcare ai\b/i;
const AGENCY_NAME = /\b(recruitment|recruiting (gmbh|ag)|staffing|personalvermittlung|personaldienst\w*|personalberatung|headhunt\w*|zeitarbeit|executive search)\b/i;
const AGENCY = /\b(personalvermittlung|arbeitnehmerüberlassung|zeitarbeit|headhunt\w*|direktvermittlung|im auftrag (unseres|eines) (kunden|mandanten)|on behalf of (our|a) client|unser (kunde|mandant),? (ist|ein))\b/i;
const CONSULTANCY_NAME = /\b(consulting|consultants?|unternehmensberatung|beratungs\w*|advisory|systemhaus|agentur|agency)\b/i;
const CONSULTANCY = /\b(unterstützen|begleiten|beraten) (wir )?(unsere[nr]?|unseren) (kunden|mandanten)\b.{0,120}\b(ki|ai|genai|copilot)\b|\b(we help|we support) (our )?(clients|customers)\b.{0,120}\b(ai|genai)\b|\b(ki|ai|genai|copilot)\b.{0,120}\b(für|bei) (unsere[nr]?|unseren) (kunden|mandanten)\b|\b(ai|ki|genai|copilot)\b.{0,100}\b(kundenprojekt\w*|client projects?)\b|\b(kundenprojekt\w*|client projects?)\b.{0,100}\b(ai|ki|genai|copilot)\b/i;

const FILLER = new Set(['gmbh', 'ag', 'se', 'kg', 'co', 'mbh', 'ug', 'inc', 'ltd', 'group', 'gruppe', 'holding', 'ev', 'de', 'deutschland', 'germany', 'recruiting']);
const keyOf = (name) => (name || '').toLowerCase().split(' - ')[0].split(/[^a-z0-9äöüß]+/).filter(t => t && !FILLER.has(t)).join('');

function rolloutHits(title, text) {
  if (CLIENT_FACING.test(title)) return [];
  const labels = ROLLOUT.filter(([, rx]) => rx.test(text)).map(([label]) => label);
  if (JUNIOR_TITLE.test(title) && OWNER_TITLE.test(title) && TITLE_AI.test(title) && !BUILDER_TITLE.test(title)) {
    labels.push('a student role in AI enablement');
  }
  return labels;
}
function isOwner(title, text) {
  if (!TITLE_AI.test(title) || BUILDER_TITLE.test(title) || JUNIOR_TITLE.test(title)) return false;
  if (PRODUCT_OR_DATA.test(title)) return rolloutHits(title, text).length > 0;
  return OWNER_TITLE.test(title);
}
function gdprNearAi(text) {
  for (const m of text.matchAll(GDPR)) {
    if (AI_WORD.test(text.slice(Math.max(0, m.index - 250), m.index + m[0].length + 250))) return m[0];
  }
  return null;
}
function excluded(name, jobs) {
  const k = keyOf(name);
  if (EXCLUDE.has(k)) return 'Langdock, a competitor, big tech or a big IT consultancy';
  if (VENDOR_NAME.test(name)) return 'name says AI company';
  const head = jobs.slice(0, 5).map(j => j.text.slice(0, 1500)).concat(jobs.map(j => j.title)).join(' ');
  if (VENDOR_TEXT.test(head)) return 'describes itself as an AI vendor';
  if (AGENCY_NAME.test(name) || AGENCY.test(jobs.map(j => j.text).join(' '))) return 'staffing or recruiting agency';
  if (CONSULTANCY_NAME.test(name) || CONSULTANCY.test(jobs.filter(j => TITLE_AI.test(j.title) || AI_WORD.test(j.text)).map(j => j.text).join(' '))) return 'sells AI or IT consulting';
  return null;
}

// ---- collect jobs from both sources, group by company
// Arbeitnow items are whole API pages ({ data: [...] }). Bundesagentur items are
// single job details (stellenangebotsTitel, stellenangebotsBeschreibung, ...).
const cleanName = (n) => { n = (n || '').replace(/\s+/g, ' ').trim(); return n.includes('@') ? n.split('@')[1] : n; };
const jobsIn = [];
for (const item of $input.all()) {
  const d = item.json || {};
  for (const j of (d.data || [])) {
    jobsIn.push({ name: j.company_name, title: j.title, text: plain(j.description), url: j.url,
                  location: (j.location || '').trim(), source: 'arbeitnow' });
  }
  if (d.stellenangebotsTitel && d.referenznummer) {
    const a = ((d.stellenlokationen || [])[0] || {}).adresse || {};
    jobsIn.push({ name: d.firma, title: d.stellenangebotsTitel, text: plain(d.stellenangebotsBeschreibung),
                  url: 'https://www.arbeitsagentur.de/jobsuche/jobdetail/' + d.referenznummer,
                  location: [a.ort, a.land].filter(Boolean).join(', ') || 'Deutschland', source: 'bundesagentur' });
  }
}
const byCompany = new Map();
const seenUrls = new Set();
for (const j of jobsIn) {
  const name = cleanName(j.name);
  const title = (j.title || '').trim();
  if (!name || seenUrls.has(j.url)) continue;
  seenUrls.add(j.url);
  if (!isDach(j.location, title + ' ' + j.text)) continue;
  const k = keyOf(name);
  if (!byCompany.has(k)) byCompany.set(k, { name, jobs: [] });
  byCompany.get(k).jobs.push({ title, text: j.text, url: j.url, location: j.location, source: j.source });
}

// ---- score
const out = [];
for (const [key, { name, jobs }] of byCompany) {
  const signals = {};
  const owner = jobs.find(j => isOwner(j.title, j.text));
  if (owner) signals.ai_owner = { why: `hiring "${owner.title}"`, url: owner.url };
  let best = null;
  for (const j of jobs) {
    const labels = rolloutHits(j.title, j.text);
    if (labels.length && (!best || labels.length > best.labels.length)) best = { j, labels };
  }
  if (best) signals.rollout = { why: `"${best.j.title}" mentions ${[...new Set(best.labels)].join(', ')}`, url: best.j.url };
  if (!Object.keys(signals).length) continue;
  if (excluded(name, jobs)) continue;
  for (const j of jobs) {
    const g = gdprNearAi(j.text);
    if (g) { signals.gdpr_ai = { why: `"${j.title}" mentions ${g} next to AI`, url: j.url }; break; }
  }
  const sizeText = jobs.map(j => (j.text.match(SIZE_TEXT) || [])[0]).find(Boolean);
  if (jobs.length >= 3) signals.size = { why: `looks mid-size or large (${jobs.length} open roles on the board, heuristic)`, url: jobs[0].url };
  else if (sizeText) signals.size = { why: `looks mid-size or large (post says "${sizeText}", heuristic)`, url: jobs[0].url };

  const order = ['ai_owner', 'rollout', 'gdpr_ai', 'size'].filter(s => signals[s]);
  out.push({ json: {
    found: new Date().toISOString().slice(0, 10),
    key,
    company: name,
    score: order.reduce((n, s) => n + POINTS[s], 0),
    signals: order.join(';'),
    why: order.map(s => `+${POINTS[s]} ${signals[s].why}`).join(' | '),
    evidence_url: signals[order[0]].url,
    location: [...new Set(jobs.map(j => j.location).filter(Boolean))].slice(0, 3).join('; '),
    sources: [...new Set(jobs.map(j => j.source))].sort().join(';'),
  } });
}
out.sort((a, b) => b.json.score - a.json.score || a.json.company.localeCompare(b.json.company));
return out;

// One Slack message with the new companies of the day.
const rows = $input.all().map(i => i.json).sort((a, b) => b.score - a.score);
if (!rows.length) return [];
const lines = rows.slice(0, 20).map(r => {
  const top = r.why.split(' | ')[0];
  return `*${r.score}* ${r.company} (${(r.location || '').split(';')[0]}): ${top} <${r.evidence_url}|job post>`;
});
const more = rows.length > 20 ? `\n...and ${rows.length - 20} more in the sheet.` : '';
return [{ json: { text: `*AI rollout signals, ${rows[0].found}*: ${rows.length} new companies in DACH\n` + lines.join('\n') + more } }];
